    assert!(-a[0] * 1 + s[0] + l[0] <= RealNumRep::new(0, 1));
    assert!(-s[3] * 1 + s[1] <= RealNumRep::new(-5, 1));
    assert!(s[4] + -s[3] * 3 + s[1] * 2 <= RealNumRep::new(0, 1));
