    assert!(-s[4] * 1 + s[2] <= RealNumRep::new(-5, 1));
    assert!(s[5] + -s[4] * 3 + s[2] * 2 <= RealNumRep::new(0, 1));
    assert!(-s[5] * 1 / 2 + s[2] * 1 / 2 <= RealNumRep::new(-5, 1));
    assert!(-s[5] * 1 / 3 + s[1] * 1 / 3 <= RealNumRep::new(-5, 1));
    assert!(-s[4] * 1 / 2 + s[1] * 1 / 2 <= RealNumRep::new(-5, 1));
    assert!(-s[5] * 1 + s[3] <= RealNumRep::new(-5, 1));
    assert!(l[1] + -a[1] * 1 + s[1] <= RealNumRep::new(0, 1));
