    assert!(-s[5] * 1 + -a[0] * 1 + s[2] * 2 + l[0] <= RealNumRep::new(0, 1));
    let tmp = IntervalList::from_interval_lists(vec![IntervalList::interval_lower(
        Bound::Excluded(s[5] * 3 / 2 + -s[4] * 3 / 2),
    )]);
