    assert!(
        (l[3] == l[2])
            || (a[5] + -a[4] * 1 + a[2] + -s[4] * 1 + -l[2] * 1 <= RealNumRep::new(0, 1))
            || (a[5] + -a[4] * 1 + -a[3] * 1 / 2 + a[1] * 1 / 2 + -l[1] * 1 / 2 + l[3] * 1 / 2
                <= RealNumRep::new(0, 1))
    );
    assert!(
        (l[4] == l[3])
            || (a[2] + -s[3] * 1 + -l[2] * 1 <= RealNumRep::new(0, 1))
            || (a[5] * 3 + -a[4] * 3 + a[1] * 3 + -s[3] * 3 + -l[1] * 3 <= RealNumRep::new(0, 1))
    );
    assert!(
        (l[3] == l[2])
            || (a[2] + -s[3] * 1 + -l[2] * 1 <= RealNumRep::new(0, 1))
            || (-a[3] * 1 + a[1] + s[1] + -s[0] * 1 + -l[1] * 1 + l[3] <= RealNumRep::new(0, 1))
    );
    assert!(
        (a[3] + -s[4] * 1 + -l[3] * 1 <= RealNumRep::new(0, 1))
            || (a[5] + -a[4] * 1 + a[2] + -s[4] * 1 + -l[2] * 1 <= RealNumRep::new(0, 1))
            || (a[5] + -a[4] * 1 + -s[4] * 1 / 2 + s[1] * 1 / 2 <= RealNumRep::new(0, 1))
    );
    assert!(
        (l[1] == l[0])
            || (a[3] + -s[4] * 1 + -l[3] * 1 <= RealNumRep::new(0, 1))
            || (a[2] + -a[1] * 1 + -s[4] * 1 + s[2] + l[1] + -l[2] * 1 <= RealNumRep::new(0, 1))
    );
    assert!(
        (l[2] == l[1])
            || (a[4] + -a[3] * 1 + -a[2] * 1 + l[3] + s[1] + l[2] + -l[4] * 1
                <= RealNumRep::new(0, 1))
    );
    assert!(
        (l[2] == l[1])
            || (a[4] * 1 / 2 + -a[2] * 1 / 2 + -s[3] * 1 + s[1] + l[2] * 1 / 2 + -l[4] * 1 / 2
                <= RealNumRep::new(0, 1))
    );
    assert!((l[1] == l[0]) || (-a[1] * 1 + s[0] + l[1] <= RealNumRep::new(-10, 1)));
    assert!(
        (l[4] == l[3])
            || (-a[4] * 2 + a[2] * 2 + s[3] * 2 + -s[2] * 2 + -l[2] * 2 + l[4] * 2
                <= RealNumRep::new(0, 1))
    );
    assert!(
        (l[2] == l[1])
            || (-a[2] * 2 + a[1] * 2 + s[3] + -s[2] * 1 + -l[1] * 2 + l[2] * 2
                <= RealNumRep::new(0, 1))
    );
    assert!(
        (a[1] + -s[2] * 1 + -l[1] * 1 <= RealNumRep::new(0, 1))
            || (s[4] * 1 / 4 + -s[2] * 1 + s[0] * 3 / 4 <= RealNumRep::new(0, 1))
    );
    assert!(
        (a[3] + -s[4] * 1 + -l[3] * 1 <= RealNumRep::new(0, 1))
            || (a[5] * 1 / 3 + -l[4] * 1 / 3 + a[2] * 2 / 3 + -s[4] * 1 + -l[2] * 2 / 3
                <= RealNumRep::new(0, 1))
            || (a[5] * 1 / 2 + -l[4] * 1 / 2 + -s[4] * 1 + s[1] * 1 / 2 <= RealNumRep::new(0, 1))
    );
    assert!(
        (a[1] + -s[2] * 1 + -l[1] * 1 <= RealNumRep::new(0, 1))
            || (a[5] * 1 / 2 + -l[4] * 1 / 2 + -a[3] * 1 / 2 + l[3] * 1 / 2 + -s[2] * 1 + s[0]
                <= RealNumRep::new(0, 1))
    );
    assert!(
        (l[3] == l[2])
            || (-a[3] * 1 / 2 + a[2] + -a[1] * 1 / 2 + -l[2] * 1 + l[1] * 1 / 2 + l[3] * 1 / 2
                <= RealNumRep::new(-5, 1))
            || (a[5] + -l[4] * 1 + -a[3] * 2 + a[1] + -l[1] * 1 + l[3] * 2
                <= RealNumRep::new(-5, 1))
    );
    assert!(
        (l[3] == l[2])
            || (-a[3] * 1 / 2 + a[2] + -a[1] * 1 / 2 + -l[2] * 1 + l[1] * 1 / 2 + l[3] * 1 / 2
                <= RealNumRep::new(-5, 1))
            || (-a[3] * 3 / 2 + a[1] * 1 / 2 + s[4] + -l[1] * 1 / 2 + l[3] * 3 / 2
                <= RealNumRep::new(-5, 1))
    );
    assert!(
        (l[4] == l[3])
            || (a[3] + -s[4] * 1 + -l[3] * 1 <= RealNumRep::new(0, 1))
            || (a[5] * 1 / 3 + -l[4] * 1 / 3 + a[2] * 2 / 3 + -s[4] * 1 + -l[2] * 2 / 3
                <= RealNumRep::new(0, 1))
            || (a[5] * 3 + -l[4] * 1 + -a[4] * 2 + a[1] * 2 + -s[4] * 3 + -l[1] * 2
                <= RealNumRep::new(0, 1))
    );
    assert!(
        (l[4] == l[3])
            || (a[5] * 1 / 2 + l[4] * 1 / 2 + -a[4] * 1 + a[3] * 1 / 2 + -l[3] * 1 / 2
                <= RealNumRep::new(-5, 1))
            || (a[5] * 2 / 3 + l[4] * 1 / 3 + -a[4] * 1 + s[2] * 1 / 3 <= RealNumRep::new(-5, 1))
    );
    assert!(
        (a[3] + -s[4] * 1 + -l[3] * 1 <= RealNumRep::new(0, 1))
            || (-a[0] * 1 + -s[4] * 1 / 2 + s[1] * 3 / 2 + l[0] <= RealNumRep::new(0, 1))
            || (a[2] + -a[0] * 1 + -s[4] * 1 + -l[2] * 1 + s[1] + l[0] <= RealNumRep::new(0, 1))
    );
    assert!(
        (l[3] == l[2])
            || (-a[3] * 1 + -a[0] * 1 / 2 + s[2] * 3 / 2 + l[3] + l[0] * 1 / 2
                <= RealNumRep::new(-5, 1))
    );
    assert!(
        (l[4] == l[3])
            || (-a[4] * 1 + a[3] + -a[0] * 1 / 2 + s[2] * 1 / 2 + -l[2] * 1 + l[4] + l[0] * 1 / 2
                <= RealNumRep::new(0, 1))
            || (!(RealNumRep::new(0, 1) <= l[2] + -l[3] * 1))
    );
    assert!(
        (a[3] + -s[4] * 1 + -l[3] * 1 <= RealNumRep::new(0, 1))
            || (a[5] * 1 / 3 + -l[4] * 1 / 3 + a[2] * 2 / 3 + -s[4] * 1 + -l[2] * 2 / 3
                <= RealNumRep::new(0, 1))
            || (a[5] + -l[4] * 1 + -s[4] * 5 / 3 + s[0] * 2 / 3 <= RealNumRep::new(0, 1))
            || (a[5] * 1 / 2 + -l[4] * 1 / 2 + a[1] * 1 / 2 + -s[4] * 1 + -l[1] * 1 / 2
                <= RealNumRep::new(0, 1))
    );
    assert!(
        (l[1] == l[0])
            || (a[4] * 3 + -a[1] * 3 + -s[4] * 3 + s[0] * 3 + l[1] * 3 + -l[4] * 3
                <= RealNumRep::new(0, 1))
    );
    assert!(
        (l[3] == l[2])
            || (-a[3] * 2 + a[1] * 2 + s[3] + -s[0] * 1 + -l[1] * 2 + l[3] * 2
                <= RealNumRep::new(0, 1))
            || (-a[3] * 1 + a[2] + a[1] + -a[0] * 1 + -l[2] * 1 + -l[1] * 1 + l[3] + l[0]
                <= RealNumRep::new(0, 1))
    );
    assert!(
        (a[3] + -s[4] * 1 + -l[3] * 1 <= RealNumRep::new(0, 1))
            || (-s[4] * 1 + s[1] * 2 + -s[0] * 1 <= RealNumRep::new(0, 1))
            || (a[2] * 2 + -s[4] * 2 + -l[2] * 2 + s[1] + -s[0] * 1 <= RealNumRep::new(0, 1))
    );
    assert!(
        (a[3] + -s[4] * 1 + -l[3] * 1 <= RealNumRep::new(0, 1))
            || (-s[4] * 2 + s[2] * 3 + -s[1] * 1 <= RealNumRep::new(0, 1))
    );
    assert!(
        (a[2] + -s[3] * 1 + -l[2] * 1 <= RealNumRep::new(0, 1))
            || (a[5] * 1 / 2 + -l[4] * 1 / 2 + -a[3] * 1 / 2 + l[3] * 1 / 2 + -s[3] * 1 + s[1]
                <= RealNumRep::new(0, 1))
    );
    assert!(
        (l[3] == l[2])
            || (a[2] + -s[3] * 1 + -l[2] * 1 <= RealNumRep::new(0, 1))
            || (a[5] * 2 + -l[4] * 2 + -a[3] * 3 + a[1] * 3 + -s[3] * 2 + -l[1] * 3 + l[3] * 3
                <= RealNumRep::new(0, 1))
    );
    assert!(
        (l[1] == l[0])
            || (-a[3] * 1 + -a[1] * 1 + s[4] + l[3] + s[0] + l[1] <= RealNumRep::new(-5, 1))
    );
    assert!(
        (l[1] == l[0])
            || (a[5] * 1 / 2
                + -l[4] * 1 / 2
                + -a[3] * 1 / 2
                + -a[1] * 1
                + l[3] * 1 / 2
                + s[0]
                + l[1]
                <= RealNumRep::new(-5, 1))
    );
    assert!(
        (l[1] == l[0])
            || (a[3] + -s[4] * 1 + -l[3] * 1 <= RealNumRep::new(0, 1))
            || (a[4] + -a[1] * 1 + -s[4] * 3 + s[2] * 3 + l[1] + -l[4] * 1
                <= RealNumRep::new(0, 1))
    );
    assert!(
        (l[3] == l[2])
            || (a[4] + -a[3] * 1 + -s[4] * 1 + s[2] + l[3] + -l[4] * 1 <= RealNumRep::new(0, 1))
    );
    assert!(
        (l[3] == l[2])
            || (a[5] * 1 / 3 + -l[4] * 1 / 3 + a[2] * 2 / 3 + -s[4] * 1 + -l[2] * 2 / 3
                <= RealNumRep::new(0, 1))
            || (a[5] + -l[4] * 1 + -a[3] * 1 + a[1] + -s[4] * 1 + -l[1] * 1 + l[3]
                <= RealNumRep::new(0, 1))
    );
    assert!(
        (l[3] == l[2])
            || (-a[3] * 1 + a[2] + a[1] + -l[2] * 1 + -s[1] * 1 + -l[1] * 1 + l[3]
                <= RealNumRep::new(0, 1))
            || (-a[3] * 5 / 2 + a[1] * 5 / 2 + s[4] + -s[0] * 1 + -l[1] * 5 / 2 + l[3] * 5 / 2
                <= RealNumRep::new(0, 1))
    );
    assert!(
        (l[3] == l[2])
            || (!(l[1] == l[0]))
            || (-a[3] * 1 + a[2] + a[1] + -l[2] * 1 + -s[1] * 1 + -l[1] * 1 + l[3]
                <= RealNumRep::new(0, 1))
            || (-a[3] * 2 + a[1] * 2 + s[4] + -s[1] * 1 + l[3] * 2 + -l[0] * 2
                <= RealNumRep::new(0, 1))
    );
    assert!(
        (l[3] == l[2])
            || (-a[3] * 2 + a[1] * 2 + s[2] * 2 + -s[1] * 2 + -l[1] * 2 + l[3] * 2
                <= RealNumRep::new(0, 1))
    );
    assert!(
        (l[3] == l[2])
            || (-a[3] * 1 + a[2] + -a[0] * 1 + s[1] + -l[2] * 1 + l[3] + l[0]
                <= RealNumRep::new(0, 1))
    );
    assert!(
        (l[3] == l[2])
            || (-a[3] * 1 + a[2] * 2 + a[1] + -s[4] * 1 + -l[2] * 2 + -s[0] * 1 + -l[1] * 1 + l[3]
                <= RealNumRep::new(0, 1))
            || (a[4] * 2 / 3 + -a[3] * 1 + a[1] * 1 / 3 + -l[1] * 1 / 3 + l[3] + -l[4] * 2 / 3
                <= RealNumRep::new(0, 1))
    );
    assert!(
        (l[3] == l[2])
            || (-a[3] * 2
                + a[2] * 2
                + a[1] * 2
                + -l[2] * 2
                + -s[2] * 1
                + -s[0] * 1
                + -l[1] * 2
                + l[3] * 2
                <= RealNumRep::new(0, 1))
            || (a[5] + -a[4] * 1 + -a[3] * 1 / 2 + a[1] * 1 / 2 + -l[1] * 1 / 2 + l[3] * 1 / 2
                <= RealNumRep::new(0, 1))
    );
    assert!(
        (a[3] + -s[4] * 1 + -l[3] * 1 <= RealNumRep::new(0, 1))
            || (a[2] + -s[4] * 1 + -l[2] * 1 <= RealNumRep::new(-5, 1))
            || (-s[4] * 1 / 2 + s[1] * 1 / 2 <= RealNumRep::new(-5, 1))
    );
    assert!(
        (l[2] == l[1])
            || (a[5] + -l[4] * 1 + -a[2] * 4 + a[1] * 4 + -s[2] * 1 + -l[1] * 4 + l[2] * 4
                <= RealNumRep::new(0, 1))
    );
    assert!(
        (l[3] == l[2])
            || (-a[3] * 1 + a[2] + a[1] + -a[0] * 1 + -l[2] * 1 + -l[1] * 1 + l[3] + l[0]
                <= RealNumRep::new(0, 1))
            || (a[5] * 2
                + -l[4] * 2
                + -a[3] * 5
                + a[1] * 5
                + -a[0] * 2
                + -l[1] * 5
                + l[3] * 5
                + l[0] * 2
                <= RealNumRep::new(0, 1))
    );
    assert!(
        (l[3] == l[2])
            || (-a[3] * 1 + a[2] + a[1] + -a[0] * 1 + -l[2] * 1 + -l[1] * 1 + l[3] + l[0]
                <= RealNumRep::new(0, 1))
            || (-a[3] * 1 + a[1] + -a[0] * 2 + s[1] * 2 + -l[1] * 1 + l[3] + l[0] * 2
                <= RealNumRep::new(0, 1))
    );
    assert!(
        (l[3] == l[2])
            || (-a[4] * 1 + a[2] + a[1] + -l[2] * 1 + -s[0] * 1 + -l[1] * 1 + l[4]
                <= RealNumRep::new(0, 1))
            || (a[4] * 2 / 3 + -a[3] * 1 + a[1] * 1 / 3 + -l[1] * 1 / 3 + l[3] + -l[4] * 2 / 3
                <= RealNumRep::new(0, 1))
            || (RealNumRep::new(0, 1) <= l[3] + -l[4] * 1)
    );
    assert!(
        (l[3] == l[2])
            || (-a[3] * 2
                + a[2] * 2
                + a[1] * 2
                + -l[2] * 2
                + -s[2] * 1
                + -s[0] * 1
                + -l[1] * 2
                + l[3] * 2
                <= RealNumRep::new(0, 1))
            || (a[4] * 2 / 3 + -a[3] * 1 + a[1] * 1 / 3 + -l[1] * 1 / 3 + l[3] + -l[4] * 2 / 3
                <= RealNumRep::new(0, 1))
    );
    assert!(
        (l[1] == l[0])
            || (a[2] + -s[3] * 1 + -l[2] * 1 <= RealNumRep::new(0, 1))
            || (a[4] + -a[1] * 1 + -s[3] * 3 + s[1] * 3 + l[1] + -l[4] * 1
                <= RealNumRep::new(0, 1))
    );
    assert!(
        (l[4] == l[3])
            || (a[5] * 1 / 2
                + l[4] * 1 / 2
                + -a[4] * 1
                + a[3] * 1 / 2
                + a[2]
                + -l[3] * 1 / 2
                + -s[3] * 1
                + -l[2] * 1
                <= RealNumRep::new(0, 1))
            || (a[5] + l[4] * 1 / 2 + -a[4] * 3 / 2 + a[2] * 3 / 2 + -s[3] * 1 + -l[2] * 3 / 2
                <= RealNumRep::new(0, 1))
    );
    assert!(
        (l[4] == l[3])
            || (a[5] * 1 / 2 + l[4] * 1 / 2 + -a[4] * 1 + a[3] * 1 / 2 + -l[3] * 1 / 2
                <= RealNumRep::new(-5, 1))
            || (a[5] + l[4] * 1 / 2 + -a[4] * 3 / 2 + a[2] * 1 / 2 + -l[2] * 1 / 2
                <= RealNumRep::new(-5, 1))
    );
    assert!(
        (l[3] == l[2])
            || (a[5] + -l[4] * 1 + -a[3] * 3 + a[2] * 3 + -s[3] * 1 + -l[2] * 3 + l[3] * 3
                <= RealNumRep::new(0, 1))
    );
    assert!(
        (l[2] == l[1])
            || (-a[3] * 1 + -a[2] * 1 + a[1] + s[4] + l[3] + -l[1] * 1 + l[2]
                <= RealNumRep::new(0, 1))
    );
    assert!(
        (l[2] == l[1])
            || (!(l[1] == l[0]))
            || (a[5] + -l[4] * 1 + -a[2] * 2 + a[1] * 2 + -s[4] * 1 + l[2] * 2 + -l[0] * 2
                <= RealNumRep::new(0, 1))
    );
    assert!(
        (l[4] == l[3])
            || (a[3] + -s[4] * 1 + -l[3] * 1 <= RealNumRep::new(0, 1))
            || (!(l[2] == l[1]))
            || (-a[4] * 1 + a[2] + s[3] * 1 / 2 + -s[0] * 1 / 2 + -l[1] * 1 + l[4]
                <= RealNumRep::new(0, 1))
    );
    assert!(
        (l[4] == l[3])
            || (-a[4] * 1 + a[2] + -a[1] * 1 + l[1] + s[3] + -l[2] * 1 + l[4]
                <= RealNumRep::new(0, 1))
    );
    assert!(
        (l[1] == l[0])
            || (a[4] + -a[2] * 1 + -a[1] * 2 + l[2] + s[0] * 2 + l[1] * 2 + -l[4] * 1
                <= RealNumRep::new(-5, 1))
    );
    assert!(
        (l[1] == l[0])
            || (a[4] + -a[2] * 1 + -a[1] * 1 + l[2] + -s[2] * 1 + s[0] * 2 + l[1] + -l[4] * 1
                <= RealNumRep::new(0, 1))
    );
    assert!(
        (l[3] == l[2])
            || (-a[3] * 2 + a[2] * 2 + -a[1] * 1 + s[3] + l[1] + -l[2] * 2 + l[3] * 2
                <= RealNumRep::new(0, 1))
    );
    assert!(
        (l[2] == l[1])
            || (-a[2] * 2 + a[1] + s[3] + -l[1] * 1 + l[2] * 2 <= RealNumRep::new(-10, 1))
            || (-a[2] * 1 + s[3] * 2 / 3 + s[0] * 1 / 3 + l[2] <= RealNumRep::new(-5, 1))
    );
    assert!(
        (l[2] == l[1])
            || (-a[2] * 1 + -a[0] * 1 + s[1] * 2 + l[2] + l[0] <= RealNumRep::new(-5, 1))
    );
    assert!(
        (l[2] == l[1])
            || (-a[2] * 4 + a[1] * 4 + -a[0] * 1 + s[4] + -l[1] * 4 + l[2] * 4 + l[0]
                <= RealNumRep::new(0, 1))
    );
    assert!(
        (l[2] == l[1])
            || (a[4] * 1 / 3 + -a[2] * 1 + a[1] * 2 / 3 + -l[1] * 2 / 3 + l[2] + -l[4] * 1 / 3
                <= RealNumRep::new(0, 1))
    );
