    ret = ret.intersection(&tmp);
    let tmp = IntervalList::from_interval_lists(vec![
        IntervalList::interval_point(Bound::Included(l[0])),
        IntervalList::interval_upper(Bound::Included(-s[5] * 1 + a[1] + C * 4 + -B * 1)),
    ]);
    ret = ret.intersection(&tmp);
