    if !(-a[1] * 1 + a[2] + -C * 1 <= RealNumRep::new(0, 1)) {
        let tmp = IntervalList::from_interval_lists(vec![IntervalList::interval_lower(
            Bound::Included(-s[5] * 1 + a[1] + C * 3 + -B * 1),
        )]);
        ret = ret.intersection(&tmp);
    }
    assert!(-a[0] * 1 + l[0] + s[4] + -C * 4 <= RealNumRep::new(0, 1));
    assert!(s[4] + -C * 4 + -s[1] * 1 <= RealNumRep::new(0, 1));
